	// ------------------------------------------------------------------
	// End-to-end correctness: the LIBRARY 10 query shape on a real store
	// ------------------------------------------------------------------

	private static final String EX = "http://example.com/library/";

	/**
	 * LIBRARY theme query 10, re-pointed at the test namespace. A branch counts iff some copy other than the branch
	 * itself is located at it, and no name of the branch contains "branch 0".
	 */
	private static String library10Query(String marker) {
		return "# arm: " + marker + "\n"
				+ "PREFIX lib: <" + EX + ">\n"
				+ "SELECT (COUNT(DISTINCT ?branch) AS ?count) WHERE {\n"
				+ "  { ?branch a lib:Branch . }\n"
				+ "  UNION\n"
				+ "  { ?branch a lib:Branch ; lib:name ?name . }\n"
				+ "  OPTIONAL { ?copy lib:locatedAt ?branch . BIND(?copy AS ?optCopy) }\n"
				+ "  FILTER(?optCopy != ?branch)\n"
				+ "  MINUS { ?branch lib:name ?name2 .\n"
				+ "          FILTER(CONTAINS(LCASE(STR(?name2)), \"branch 0\")) }\n"
				+ "}";
	}

	@org.junit.jupiter.api.io.TempDir
	java.io.File dataDir;

	private org.eclipse.rdf4j.repository.sail.SailRepository repository;

	@org.junit.jupiter.api.AfterEach
	void tearDown() {
		if (repository != null) {
			repository.shutDown();
		}
	}

	private void openLibraryRepository() {
		repository = new org.eclipse.rdf4j.repository.sail.SailRepository(
				new org.eclipse.rdf4j.sail.lmdb.LmdbStore(dataDir,
						new org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig("spoc,ospc,psoc,posc")));
		try (org.eclipse.rdf4j.repository.sail.SailRepositoryConnection conn = repository.getConnection()) {
			org.eclipse.rdf4j.model.ValueFactory vf = conn.getValueFactory();
			org.eclipse.rdf4j.model.IRI branchClass = vf.createIRI(EX, "Branch");
			org.eclipse.rdf4j.model.IRI name = vf.createIRI(EX, "name");
			org.eclipse.rdf4j.model.IRI locatedAt = vf.createIRI(EX, "locatedAt");
			org.eclipse.rdf4j.model.IRI[] b = new org.eclipse.rdf4j.model.IRI[5];
			for (int i = 0; i < b.length; i++) {
				b[i] = vf.createIRI(EX, "b" + i);
			}
			conn.begin();
			for (org.eclipse.rdf4j.model.IRI branch : b) {
				conn.add(branch, org.eclipse.rdf4j.model.vocabulary.RDF.TYPE, branchClass);
			}
			// b0 is pruned by the MINUS ("branch 0" name) even though it has a foreign copy.
			conn.add(b[0], name, vf.createLiteral("Branch 0 Central"));
			conn.add(vf.createIRI(EX, "c1"), locatedAt, b[0]);
			// b1 qualifies: named, one foreign copy. Its type triple is duplicated into a named graph, so the
			// class-extent domain enumerates b1 twice — a COUNT(*) shortcut would count 3 instead of 2.
			conn.add(b[1], name, vf.createLiteral("Branch 1"));
			conn.add(vf.createIRI(EX, "c2"), locatedAt, b[1]);
			conn.add(b[1], org.eclipse.rdf4j.model.vocabulary.RDF.TYPE, branchClass, vf.createIRI(EX, "g1"));
			// b2 fails the filter: its only copy is itself.
			conn.add(b[2], name, vf.createLiteral("Branch 2"));
			conn.add(b[2], locatedAt, b[2]);
			// b3 qualifies: unnamed (union arm 1 only), one foreign copy.
			conn.add(vf.createIRI(EX, "c3"), locatedAt, b[3]);
			// b4 fails the filter: no copies at all, so the OPTIONAL stays unbound.
			conn.add(b[4], name, vf.createLiteral("Branch 4"));
			conn.commit();
		}
	}

	private long count(String query) {
		try (org.eclipse.rdf4j.repository.sail.SailRepositoryConnection conn = repository.getConnection()) {
			List<org.eclipse.rdf4j.query.BindingSet> result = org.eclipse.rdf4j.query.QueryResults
					.asList(conn.prepareTupleQuery(query).evaluate());
			assertEquals(1, result.size());
			return ((org.eclipse.rdf4j.model.Literal) result.get(0).getValue("count")).longValue();
		}
	}

	private static void withProperty(String property, String value, Runnable action) {
		String previous = System.getProperty(property);
		if (value == null) {
			System.clearProperty(property);
		} else {
			System.setProperty(property, value);
		}
		try {
			action.run();
		} finally {
			if (previous == null) {
				System.clearProperty(property);
			} else {
				System.setProperty(property, previous);
			}
		}
	}

	@Test
	void library10ShapeCountsIdenticallyWithTheRewriteOnAndOff() {
		openLibraryRepository();
		long expected = 2L; // b1 and b3

		assertEquals(expected, count(library10Query("default")), "default settings");
		withProperty(LmdbNativeKernelIr.DISTINCT_ROOT_EXISTS_PROPERTY, "false",
				() -> assertEquals(expected, count(library10Query("rewrite-off")), "rewrite disabled"));
		withProperty(LmdbNativeJaninoCodegen.ENABLED_PROPERTY, "false", () -> {
			assertEquals(expected, count(library10Query("janino-off")), "janino disabled");
			withProperty(LmdbNativeKernelIr.DISTINCT_ROOT_EXISTS_PROPERTY, "false",
					() -> assertEquals(expected, count(library10Query("janino-off-rewrite-off")),
							"janino and rewrite disabled"));
		});
		withProperty("rdf4j.lmdb.janinoCodegen.synchronous", "true",
				() -> withProperty(LmdbNativeJaninoCodegen.THRESHOLD_ROWS_PROPERTY, "0",
						() -> assertEquals(expected, count(library10Query("janino-sync")),
								"synchronously compiled kernels")));
	}
